// AI pre-translation of PDF Editor monorepo keys with EMPTY targets in the new locales (da, fi, no, pl).
// Context per key: EN source, reviewed Spanish as reference/fallback, key name, description, char limit, tags,
// screenshots (images attached), live glossary, Drive style guides, PDF TM. Writes only empty targets,
// EN unchanged, non-archived, unverified + AI_TO_REVIEW. Plural keys: hand-written in PLURALS.
// Run 02.11.26: sample check exec 949119 (25 keys/lang), then full write. Set MODE back to 'check' after a run.
const MODE = 'write';
const SAMPLE = 0;             // max keys per language (0 = all)
const PID = '479073796a6095e8c10e35.09051894';
const LANGS = ['da', 'fi', 'no', 'pl'];
const REF = 'es';
const CHUNK = 40;
const NOTES = [
 'PRODUCT: PDF Help (internal: PDF Editor monorepo) is a web app with online PDF tools: edit, sign, annotate, convert (PDF to/from Word, Excel, PowerPoint, JPG, PNG, image to text), merge, split, compress PDFs, plus online filling of official government forms (US IRS/USCIS forms such as W-9, I-9, I-864; Canadian CRA forms such as T4, TD1; Australian forms such as SU580, NAT 3092, statutory declaration). Paid subscription with trials.',
 'BRAND: PDF Help is never translated. Finnish: avoid case endings on the brand where a natural rephrasing exists (PDF Help -palvelussa). Polish: w PDF Help, z PDF Help.',
 'PLACEHOLDERS ARE NOT TEXT: [%1$s:appName] is replaced by the app name at runtime. NEVER replace any placeholder with a brand name or any other text, never drop it, never add one. Build the sentence around it (Danish/Norwegian: [%1$s:appName]-konto; Finnish: [%1$s:appName]-palvelussa).',
 'FORMS: keep form codes exactly (W-9, I-864, T4, TD1, NAT 3092, SU580), including any non-breaking hyphen in the source; keep agency names (IRS, USCIS, CRA, Services Australia, Australian Government); translate the descriptive part of form titles.',
 'FORMATS: PDF, Word, Excel, PowerPoint, JPG, PNG, XLSX, PPTX, DOCX unchanged.',
 'SEO: keys under metadata:: are page title, meta description and Open Graph tags. Keep the suffix - PDF Help or | PDF Help exactly as in the source; natural search phrasing a native user would type; about the same length as the source.',
 'EMAILS: welcomeWithOrder, welcomeNoOrder, resetPassword, cancellationEmail, accountDeleted, orderDetails, subjects are transactional emails.',
 'MARKUP: tags like <terms>...</terms>, <privacy>, <email>, <b>, <strong>, <a href=...>, <ul><li> stay exactly as in the source (same count); translate the text between tags. A # in a string is a number placeholder: keep it.',
 'NATURALNESS: do not carry over English filler. Do not translate successfully literally (Norwegian: er slettet, not er slettet vellykket; Danish: er slettet; Finnish: on poistettu); drop please and we are writing to confirm style padding where the target language would not use it.',
 'POLISH GENDER: the user must never be addressed with gendered forms. No masculine or feminine participles or past-tense verbs for the user (not: zostaniesz obciążony, abyś pracował, zalogowałeś się, jesteś pewien). Use impersonal forms, nouns, or 2nd person present/future that are gender-neutral (Nie pobierzemy już żadnych opłat; pracuj sprawniej; Zalogowano; Czy na pewno chcesz...).',
 'SPANISH REFERENCE: each item carries the reviewed Spanish translation (es). It was reviewed by a linguist and is the most reliable reading of the intent. Translate from English, but use the Spanish to resolve anything ambiguous, idiomatic, twisted or under-specified in the English (meaning, which object, who does what, register of an email), and follow the Spanish when English and Spanish differ in meaning or when the Spanish adds a clarifying object (e.g. cancel -> cancel your subscription). Never copy Spanish typography or number formats; never translate from Spanish word-for-word.',
 'KEY INFO: read the key name (where the text sits: title, button, cta, label, faq question/answer, toast, error, ogTitle...), the description and tags. A description may ask for a shorter text, a transcreation or an alternative version: follow it. Respect char_limit when given. Screenshots, when attached, show where the text appears: use them to choose button vs heading forms and length.'
].join(' ');
const TERM_TAG = /pdf/i;      // glossary tags in scope (plus shared / untagged)
const PLURALS = {
 '899112195': {
  da: { one: '# side', other: '# sider' },
  no: { one: '# side', other: '# sider' },
  fi: { one: '# sivu', other: '# sivua' },
  pl: { one: '# strona', few: '# strony', many: '# stron', other: '# strony' } },
 '962576229': {
  da: { one: 'Du har oprettet [%1$s:n] dokument med PDF Help. Efter [%1$s:end_date] kan du ikke længere downloade det.', other: 'Du har oprettet [%1$s:n] dokumenter med PDF Help. Efter [%1$s:end_date] kan du ikke længere downloade nogen af dem.' },
  no: { one: 'Du har opprettet [%1$s:n] dokument med PDF Help. Etter [%1$s:end_date] kan du ikke lenger laste det ned.', other: 'Du har opprettet [%1$s:n] dokumenter med PDF Help. Etter [%1$s:end_date] kan du ikke lenger laste ned noen av dem.' },
  fi: { one: 'Olet luonut [%1$s:n] asiakirjan PDF Help -palvelussa. Päivämäärän [%1$s:end_date] jälkeen et voi enää ladata sitä.', other: 'Olet luonut [%1$s:n] asiakirjaa PDF Help -palvelussa. Päivämäärän [%1$s:end_date] jälkeen et voi enää ladata niitä.' },
  pl: { one: 'Utworzono [%1$s:n] dokument w PDF Help. Po [%1$s:end_date] nie będzie można go pobrać.', few: 'Utworzono [%1$s:n] dokumenty w PDF Help. Po [%1$s:end_date] nie będzie można pobrać żadnego z nich.', many: 'Utworzono [%1$s:n] dokumentów w PDF Help. Po [%1$s:end_date] nie będzie można pobrać żadnego z nich.', other: 'Utworzono [%1$s:n] dokumentu w PDF Help. Po [%1$s:end_date] nie będzie można pobrać żadnego z nich.' } },
 '962576231': {
  da: { one: '[%1$s:n] af dine dokumenter bliver låst den [%1$s:end_date]', other: '[%1$s:n] af dine dokumenter bliver låst den [%1$s:end_date]' },
  no: { one: '[%1$s:n] av dokumentene dine blir låst [%1$s:end_date]', other: '[%1$s:n] av dokumentene dine blir låst [%1$s:end_date]' },
  fi: { one: '[%1$s:n] asiakirjoistasi lukitaan [%1$s:end_date]', other: '[%1$s:n] asiakirjoistasi lukitaan [%1$s:end_date]' },
  pl: { one: '[%1$s:n] z twoich dokumentów zostanie zablokowany dnia [%1$s:end_date]', few: '[%1$s:n] z twoich dokumentów zostaną zablokowane dnia [%1$s:end_date]', many: '[%1$s:n] z twoich dokumentów zostanie zablokowanych dnia [%1$s:end_date]', other: '[%1$s:n] z twoich dokumentów zostanie zablokowane dnia [%1$s:end_date]' } }
