}
const NL = String.fromCharCode(10);
const jobs = []; const plan = {};
for (const iso of cfg.langs) {
  let todo = targets.filter(function (t) { return !t.t[iso]; });
  if (cfg.sample) { todo = todo.slice(0, cfg.sample); }
  plan[iso] = todo.length;
  if (!todo.length) { continue; }
  const fb = (FB[iso] || []).slice(-15);
  for (let c = 0; c < todo.length; c += cfg.chunk) {
