    const items = part.map(function (t) {
      const tm = [];
      for (const e of t.ex) { if (e.t[iso]) { tm.push({ match: '100% (exact)', key: e.name, en: e.en, translation: e.t[iso] }); } }
      for (const f of t.fz) { if (f.c.t[iso]) { tm.push({ match: 'fuzzy ' + Math.round(f.sc * 100) + '%', en: f.c.en, translation: f.c.t[iso] }); } }
      const sh = t.shots.map(function (s) { return (imgIdx[s.url] !== undefined ? 'image ' + (imgIdx[s.url] + 1) + ': ' : '') + s.title + (s.desc ? ' – ' + s.desc : ''); });
      return { id: String(t.id), key: t.name, en: t.en, es: t.t[cfg.ref] || undefined, description: t.d.slice(0, 900) || undefined, char_limit: t.cl || undefined, tags: t.tags.length ? t.tags : undefined, screenshots: sh.length ? sh : undefined, tm: tm.length ? tm.slice(0, 4) : undefined };
    });
    const SYS = [
      'You are a senior native ' + LN[iso] + ' localizer translating the web app PDF Help into ' + LN[iso] + '. This is a NEW locale: write the first, publishable ' + LN[iso] + ' version of every string.',
      'Write natural, idiomatic, concise product copy a native speaker expects in a polished web app, not a literal rendering.',
      'PRIORITIES, in order: (1) the GLOSSARY (approved target terms; never forbidden terms; brand names unchanged); (2) the ' + LN[iso] + ' STYLE GUIDE below (register, tone, grammar of buttons vs headings, typography, number/date/currency conventions); (3) KEY INFO (key name, description, char_limit, tags, screenshots); (4) the reviewed SPANISH reference for meaning; (5) TRANSLATION MEMORY from our other PDF projects in ' + LN[iso] + ': reuse 100% matches unless they break (1)-(3); reuse terminology from fuzzy matches.',
      cfg.notes,
      'MECHANICS (strict): keep every placeholder exactly (e.g. [%1$s:price], #) and every tag exactly (same count, same attributes). No leading/trailing spaces unless the source has them. Identical English strings must get identical translations. Strings that are only codes, file formats or names (W-9, PPTX, [%1$s:type]) stay as in the source.',
      'Return ONLY JSON: {"t":{"<id>":"<translation>", ...}} keyed by the numeric item id, with an entry for EVERY id.',
      '',
      '=== ' + LN[iso] + ' STYLE GUIDE (source of truth) ===',
      GUIDE[iso] || '(guide unavailable)',
      '',
      '=== Style rules distilled by the i18n team ===',
      (RULES[iso] || []).slice(0, 40).join(NL) || '(none)',
      JUDGE[iso] ? ('Judgement notes: ' + JUDGE[iso]) : '',
      fb.length ? ('Reviewer precedent (i18n lead decisions on earlier audits, follow them): ' + JSON.stringify(fb)) : ''
    ].join(NL);
    const user = { language: LN[iso], glossary: glossFor(iso, part.map(function (t) { return t.en; })), items: items };
    let content = JSON.stringify(user);
    if (imgs.length) {
      content = [{ type: 'text', text: JSON.stringify(user) + NL + 'Attached screenshots (image 1..' + imgs.length + ') show where some of these strings appear.' }].concat(imgs.map(function (s) { return { type: 'image_url', image_url: { url: s.url, detail: 'low' } }; }));
    }
    jobs.push({ json: { iso: iso, chunk: c / cfg.chunk, ids: part.map(function (t) { return t.id; }), items: items.map(function (x) { return { id: x.id, key: x.key, en: x.en, es: x.es, tm: x.tm ? x.tm[0].match : '' }; }), imgs: imgs.length, gloss_n: user.glossary.length, gloss_tags: allTags, plan: plan, seen_target: seenTarget, targets: targets.length,
      body: JSON.stringify({ model: 'gpt-4.1', temperature: 0.2, max_tokens: 16000, response_format: { type: 'json_object' }, messages: [{ role: 'system', content: SYS }, { role: 'user', content: content }] }) } });
  }
