  if (!t || !String(t).trim()) { return 'empty'; }
  if (bag(en, PH) !== bag(t, PH)) { return 'placeholder mismatch'; }
  if (bag(en, TAG) !== bag(t, TAG)) { return 'tag mismatch'; }
  const letters = /\p{L}/u.test(String(en).replace(PH, ''));
  if (letters && String(t).trim() === String(en).trim() && /(^|[^\p{L}])\p{Ll}{4,}/u.test(String(en).replace(PH, '').replace(/<[^>]+>/g, ''))) { return 'untranslated'; }
  if (t !== t.trim() && en === en.trim()) { return 'extra whitespace'; }
  return '';
}
const per = {}; const bad = []; const callErr = [];
for (let i = 0; i < jobs.length; i++) {
  const j = jobs[i]; const r = res[i] || {};
  let parsed = null;
  try { parsed = JSON.parse(String(r.choices[0].message.content).replace(/^```json|```$/g, '').trim()).t; } catch (e) { callErr.push({ iso: j.iso, chunk: j.chunk, imgs: j.imgs, err: r.error ? JSON.stringify(r.error).slice(0, 300) : String(e.message || e) }); continue; }
  per[j.iso] = per[j.iso] || {};
  for (const it of j.items) {
    const t = parsed ? (parsed[it.id] !== undefined ? parsed[it.id] : parsed[it.key]) : undefined;
    if (typeof t !== 'string') { bad.push({ iso: j.iso, id: it.id, key: it.key, why: 'missing in answer' }); continue; }
    const why = check(it.en, t);
    if (why) { bad.push({ iso: j.iso, id: it.id, key: it.key, why: why, en: it.en.slice(0, 200), t: String(t).slice(0, 300) }); continue; }
    per[j.iso][it.id] = { key: it.key, en: it.en, es: it.es || '', t: t, tm: it.tm || '' };
  }
}
let unified = 0;
for (const iso in per) {
  const groups = {};
  for (const id in per[iso]) { const e = per[iso][id].en.trim(); (groups[e] = groups[e] || []).push(id); }
  for (const e in groups) {
    const ids = groups[e]; if (ids.length < 2) { continue; }
    const cnt = {}; for (const id of ids) { const t = per[iso][id].t; cnt[t] = (cnt[t] || 0) + 1; }
    const best = Object.keys(cnt).sort(function (a, b) { return cnt[b] - cnt[a]; })[0];
    for (const id of ids) { if (per[iso][id].t !== best) { per[iso][id].t = best; unified++; } }
  }
}
const stats = {}; for (const iso in per) { const v = Object.values(per[iso]); stats[iso] = { ok: v.length, tm_exact_reused: v.filter(function (x) { return x.tm.indexOf('100%') === 0; }).length }; }
const j0 = jobs[0] || {};
return [{ json: { per: per, bad: bad, call_errors: callErr, unified: unified, stats: stats, plan: j0.plan, targets: j0.targets, seen_target: j0.seen_target, gloss_tags: j0.gloss_tags, jobs: jobs.length, gloss_per_job: jobs.map(function (j) { return j.iso + j.chunk + ':' + j.gloss_n; }).join(' ') } }];

// Guard: writes only into translations that are still empty right now, only if EN is unchanged, never archived keys.
// Status: unverified + the project's AI_TO_REVIEW custom status (looked up live; skipped if the project has none).
const p = $('Parse and validate').first().json; const cfg = $('Config').first().json;
const live = {}; const gstat = [];
for (const it of $('Guard fetch').all()) {
  const b = it.json.body || {}; gstat.push(it.json.statusCode);
  if (!Array.isArray(b.keys)) { throw new Error('Guard fetch failed: ' + JSON.stringify(b).slice(0, 200)); }
  for (const k of b.keys) { const m = {}; for (const t of (k.translations || [])) { m[t.language_iso] = t.translation; } live[k.key_id] = { m: m, arch: k.is_archived, pl: k.is_plural }; }
}
const sb = $('Statuses').first().json.body || {};
